import { setTimeout as sleep } from 'node:timers/promises';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase, immediate } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_FAILURE, type JobRow } from './jobs.ts';

const db: DatabaseSync = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, seen_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET seen_at = excluded.seen_at',
  ).run(Date.now());
}

/** Runs `fn`, logging and swallowing errors so that one transient failure does not stop the worker. */
function safely(what: string, fn: () => void): void {
  try {
    fn();
  } catch (e) {
    console.error(`${what} failed, will retry:`, e);
  }
}

interface ClaimedJob {
  id: string;
  steps: number;
  input: string;
  attempt: number;
  /** True when this attempt is designated to fail at its first step. */
  failing: boolean;
}

/**
 * Takes the oldest ready queued job and starts an attempt on it: status `running`, `attempts`
 * incremented, progress reset to 0. Every attempt is claimed this way, including failing ones.
 */
function claimNext(): ClaimedJob | null {
  return immediate(db, () => {
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY rowid ASC LIMIT 1")
      .get(Date.now()) as JobRow | undefined;
    if (!row) return null;
    const attempt = row.attempts + 1;
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
    ).run(attempt, new Date().toISOString(), row.id);
    return { id: row.id, steps: row.steps, input: row.input, attempt, failing: attempt <= row.fail_attempts };
  });
}

/** Ends a failing attempt: requeue with a retry delay, or fail the job after the last attempt. */
function finishFailedAttempt(job: ClaimedJob): void {
  const now = new Date().toISOString();
  if (job.attempt >= MAX_ATTEMPTS) {
    db.prepare(
      "UPDATE jobs SET status = 'failed', progress_completed = 0, error = ?, output = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
    ).run(TRANSIENT_FAILURE, now, job.id);
  } else {
    db.prepare(
      "UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
    ).run(Date.now() + RETRY_DELAY_MS, now, job.id);
  }
}

/**
 * Gives an unfinished attempt back: the job is queued again and the attempt is not counted, so the
 * next claim runs the same attempt number from the beginning.
 */
function releaseJob(id: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(new Date().toISOString(), id);
}

/** Runs one claimed attempt. */
async function runAttempt(job: ClaimedJob): Promise<void> {
  if (job.failing) {
    finishFailedAttempt(job);
    return;
  }
  for (let i = 1; i <= job.steps; i++) {
    if (stopping) {
      releaseJob(job.id);
      return;
    }
    await sleep(STEP_MS);
    db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(
      i,
      new Date().toISOString(),
      job.id,
    );
  }
  db.prepare(
    "UPDATE jobs SET status = 'completed', output = ?, progress_completed = steps, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

async function main(): Promise<void> {
  // A job left running by a worker that died is processed again. Its interrupted attempt is not
  // counted, so the rerun uses the same attempt number and the 3-attempt limit still holds.
  db.prepare(
    "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, updated_at = ? WHERE status = 'running'",
  ).run(new Date().toISOString());
  heartbeat();
  const beat = setInterval(() => {
    if (!stopping) safely('heartbeat', heartbeat);
  }, 1000);

  console.log('worker started');
  while (!stopping) {
    let current: ClaimedJob | null = null;
    try {
      current = claimNext();
      if (current) await runAttempt(current);
      else await sleep(100);
    } catch (e) {
      console.error('worker iteration failed, will retry:', e);
      if (current) safely('releasing job', () => releaseJob(current!.id));
      await sleep(500);
    }
  }
  clearInterval(beat);
  db.close();
  console.log('worker stopped');
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});

