    if (!row) return null;
    const attempt = row.attempts + 1;
    const now = new Date().toISOString();
    if (attempt <= row.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) {
        db.prepare(
          "UPDATE jobs SET status = 'failed', attempts = ?, progress_completed = 0, error = ?, output = NULL, updated_at = ? WHERE id = ?",
