  // Jobs left running by a worker that died are processed again.
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at = ? WHERE status = 'running'").run(
    new Date().toISOString(),
  );
  heartbeat();
  const beat = setInterval(() => {
    if (!stopping) heartbeat();
  }, 1000);

  console.log('worker started');
  while (!stopping) {
    const job = claimNext();
    if (job) await runAttempt(job);
    else await sleep(100);
  }
  clearInterval(beat);
  db.close();
  console.log('worker stopped');
